namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile setup is complete.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = _nextId++, Message = "New feature: dark mode is now available.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        ]);
    }

    /// <summary>Returns all notifications.</summary>
    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>Returns only notifications newer than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNewerThanAsync(int sinceId)
    {
        lock (_lock)
        {
            // Simulate a new notification arriving roughly every 10 seconds.
            if (_notifications.Count == 0 || Random.Shared.NextDouble() < 0.5)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = $"New event at {DateTime.UtcNow:T} — item #{_nextId - 1}",
                    Timestamp = DateTime.UtcNow
                });
            }

            return Task.FromResult(
                _notifications
                    .Where(n => n.Id > sinceId)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

