@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted ms-3">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? _notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when the value wasn't restored from prerender state.
        _notifications ??= await NotificationSvc.GetAllAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender never fires during prerender — only when interactive.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Determine the high-water mark so we only fetch new items.
        var sinceId = _notifications?.MaxBy(n => n.Id)?.Id ?? 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationSvc.GetNewerThanAsync(sinceId);
            if (newer.Count > 0)
            {
                sinceId = newer.Max(n => n.Id);
                _notifications = [..newer, ..(_notifications ?? [])];
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

