+        ]);
+    }
+
+    /// <summary>Returns all notifications.</summary>
+    public Task<List<Notification>> GetAllAsync()
+    {
+        lock (_lock)
+        {
+            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
+        }
+    }
+
+    /// <summary>Returns only notifications newer than <paramref name="sinceId"/>.</summary>
+    public Task<List<Notification>> GetNewerThanAsync(int sinceId)
+    {
+        lock (_lock)
+        {
+            // Simulate a new notification arriving roughly every 10 seconds.
+            if (_notifications.Count == 0 || Random.Shared.NextDouble() < 0.5)
+            {
+                _notifications.Add(new Notification
+                {
+                    Id = _nextId++,
+                    Message = $"New event at {DateTime.UtcNow:T} — item #{_nextId - 1}",
+                    Timestamp = DateTime.UtcNow
+                });
+            }
+
+            return Task.FromResult(
+                _notifications
+                    .Where(n => n.Id > sinceId)
+                    .OrderByDescending(n => n.Timestamp)
+                    .ToList());
+        }
+    }
+}
